test:
events = [
    {'track_id': 'beta', 'country': 'US'},
    {'track_id': 'alpha', 'country': 'US'},
    {'track_id': 'beta', 'country': 'CA'},
    {'track_id': 'alpha', 'country': 'CA'},
    {'track_id': 'gamma', 'country': 'CA'},
]
assert top_played_tracks(events, 1) == {
    'global': [('alpha', 2)],
    'by_country': {'CA': [('alpha', 1)], 'US': [('alpha', 1)]},
}
assert top_played_tracks(events, 5) == {
    'global': [('alpha', 2), ('beta', 2), ('gamma', 1)],
    'by_country': {
        'CA': [('alpha', 1), ('beta', 1), ('gamma', 1)],
        'US': [('alpha', 1), ('beta', 1)],
    },
}
assert top_played_tracks(events, 0) == {
    'global': [],
    'by_country': {'CA': [], 'US': []},
}

assert top_played_tracks([], 3) == {'global': [], 'by_country': {}}
invalid_calls = [
    lambda: top_played_tracks([], -1),
    lambda: top_played_tracks([], True),
    lambda: top_played_tracks([], 1.5),
    lambda: top_played_tracks([{'track_id': 'a'}], 1),
    lambda: top_played_tracks([{'track_id': '', 'country': 'US'}], 1),
    lambda: top_played_tracks([{'track_id': 'a', 'country': ''}], 1),
    lambda: top_played_tracks([('a', 'US')], 1),
]
for call in invalid_calls:
    try:
        call()
        raise AssertionError('expected ValueError')
    except ValueError:
        pass
